def check_wal_horizon(dsn: str, max_retries: int = 3) -> list[dict]:
    query = '''
        SELECT slot_name, active,
               pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn) AS lag_bytes
        FROM pg_replication_slots
        WHERE restart_lsn IS NOT NULL;
    '''
    for attempt in range(max_retries):
        try:
            with psycopg.connect(dsn, connect_timeout=3) as conn:
                with conn.cursor() as cur:
                    cur.execute('SET statement_timeout = 2000')
                    cur.execute(query)
                    rows = cur.fetchall()
                    return [
                        {'slot': r[0], 'active': r[1], 'lag_gb': round(r[2] / 1e9, 2)}
                        for r in rows if r[2] and r[2] > WARN_BYTES
                    ]
        except psycopg.OperationalError as exc:
            if attempt == max_retries - 1:
                raise RuntimeError(f'WAL watchdog failed after {max_retries} attempts: {exc}') from exc
            time.sleep((0.5 * (2 ** attempt)) + random.uniform(0, 0.25))
    return []
